import 'package:dart_tui/dart_tui.dart';

import 'package:flutter_agent_harness/src/cli/fa_tui.dart';
import 'package:flutter_agent_harness/src/cli/tui_prompt.dart';
import 'package:test/test.dart';

FaTuiModel buildSheet({
  required Future<PasteboardRead> Function()? textReader,
  DateTime Function()? now,
}) {
  return FaTuiModel(
    callbacks: FaTuiCallbacks(
      onSubmit: (line, {images = const []}) async {},
      onSteer: (messages, {images}) async {},
      onModelSelected: (_) async {},
      buildSlashMenu: (_) => const [],
      buildModelMenu: (_, _) => const [],
      statusLine: () => 'test',
      prompt: 'fa> ',
      readClipboardText: textReader,
    ),
    isExited: () => false,
    termHeight: 12,
    now: now,
  ).copyWith(
    prompt: TuiPromptState(SecretPromptSpec(name: 'KEY', reason: 'r')),
  );
}

void main() {
  test('SCRATCH: ctrl+v + twin bracketed paste in one gesture (sheet)', () async {
    final model = buildSheet(
      textReader: () async => const PasteboardText('sk-token'),
    );
    // 1. The ctrl+v key event arrives...
    final (m1, keyCmd) = model.update(
      KeyPressMsg(
        const TeaKey(code: KeyCode.rune, text: 'v', modifiers: {KeyMod.ctrl}),
      ),
    );
    // 2. ...and the terminal's own bracketed paste of the SAME action lands
    //    back-to-back (the issue #1067 twin delivery the composer path
    //    absorbs via the 500ms gesture window).
    final (m2, pasteCmd) = (m1 as FaTuiModel).update(PasteMsg('sk-token'));
    // 3. The async clipboard read lands.
    final readResult = await keyCmd?.call();
    final (m3, _) = (m2 as FaTuiModel).update(readResult!);

    final value = ((m3 as FaTuiModel).prompt)?.secretValue;
    // ignore: avoid_print
    print('TWIN-GESTURE sheet secretValue = "$value"');
    expect(pasteCmd, isNull, reason: 'no probe twin in prompt mode');
    expect(value, 'sk-tokensk-token', reason: 'DEMONSTRATES the double insert');
  });

  test('SCRATCH: sheet closed while the read is in flight is a no-op', () async {
    var model = buildSheet(
      textReader: () async => const PasteboardText('sk-token'),
    );
    final (next, cmd) = model.update(
      KeyPressMsg(
        const TeaKey(code: KeyCode.rune, text: 'v', modifiers: {KeyMod.ctrl}),
      ),
    );
    // The sheet closed (Esc) before the async read landed.
    final closed = (next as FaTuiModel).copyWith(clearPrompt: true);
    final followUp = await cmd?.call();
    final (after, _) = closed.update(followUp!);
    expect((after as FaTuiModel).prompt, isNull);
  });
}

