import 'package:dart_tui/dart_tui.dart';

import 'package:flutter_agent_harness/src/cli/fa_tui.dart';
import 'package:flutter_agent_harness/src/cli/paste_image.dart';
import 'package:flutter_agent_harness/src/cli/tui_prompt.dart';
import 'package:test/test.dart';

FaTuiModel sheetWith({
  required Future<PasteboardRead> Function()? textReader,
  DateTime Function()? now,
}) =>
    FaTuiModel(
      callbacks: FaTuiCallbacks(
        onSubmit: (line, {images = const []}) async {},
        onSteer: (messages, {images}) async {},
        onModelSelected: (_) async {},
        buildSlashMenu: (_) => const [],
        buildModelMenu: (_, _) => const [],
        statusLine: () => 'test',
        prompt: 'fa> ',
        readClipboardText: textReader,
      ),
      isExited: () => false,
      termHeight: 12,
      now: now,
    ).copyWith(
      prompt: TuiPromptState(SecretPromptSpec(name: 'KEY', reason: 'r')),
    );

KeyPressMsg ctrlV() => KeyPressMsg(
  const TeaKey(code: KeyCode.rune, text: 'v', modifiers: {KeyMod.ctrl}),
);

void main() {
  test('PROBE 1: original repro — key ctrl+v + twin PasteMsg inserts once',
      () async {
    var t = 1000;
    var model = sheetWith(
      textReader: () async => const PasteboardText('sk-token'),
      now: () => DateTime.fromMillisecondsSinceEpoch(t),
    );
    final (m1, keyCmd) = model.update(ctrlV());
    final (m2, _) = (m1 as FaTuiModel).update(PasteMsg('sk-token'));
    final result = await keyCmd?.call();
    final (m3, _) = (m2 as FaTuiModel).update(result!);
    // ignore: avoid_print
    print('PROBE1 secretValue = "${(m3 as FaTuiModel).prompt?.secretValue}"');
    expect((m3 as FaTuiModel).prompt?.secretValue, 'sk-token');
  });

  test('PROBE 2: slow read (window expired, no newer gesture) still lands',
      () async {
    var t = 1000;
    var model = sheetWith(
      textReader: () async {
        t += 800; // read takes 800ms — beyond the 500ms gesture window
        return const PasteboardText('slow-token');
      },
      now: () => DateTime.fromMillisecondsSinceEpoch(t),
    );
    final (m1, keyCmd) = model.update(ctrlV());
    final result = await keyCmd?.call();
    final (m2, _) = (m1 as FaTuiModel).update(result!);
    // ignore: avoid_print
    print('PROBE2 secretValue = "${(m2 as FaTuiModel).prompt?.secretValue}"');
    expect(
      (m2 as FaTuiModel).prompt?.secretValue,
      'slow-token',
      reason: 'a slow read must not be silently dropped',
    );
  });

  test('PROBE 3: bracketed paste takes the gesture over → stale result dropped',
      () async {
    var t = 1000;
    var model = sheetWith(
      textReader: () async {
        t += 600; // read lands at t=1600
        return const PasteboardText('stale-clipboard');
      },
      now: () => DateTime.fromMillisecondsSinceEpoch(t),
    );
    final (m1, keyCmd) = model.update(ctrlV()); // arms at t=1000
    t = 700; // window expired: a NEW user paste arrives at t=700 (wall clock model)
    final (m2, _) = (m1 as FaTuiModel).update(PasteMsg('fresh-paste'));
    // The fresh paste inserted and re-armed the stamp.
    expect((m2 as FaTuiModel).prompt?.secretValue, 'fresh-paste');
    final result = await keyCmd?.call();
    final (m3, _) = (m2 as FaTuiModel).update(result!);
    // ignore: avoid_print
    print('PROBE3 secretValue = "${(m3 as FaTuiModel).prompt?.secretValue}"');
    expect(
      (m3 as FaTuiModel).prompt?.secretValue,
      'fresh-paste',
      reason: 'the stale read must not append after the newer paste',
    );
  });
}

